package main

import (
	"net/http"

	"github.com/gin-gonic/gin"
)

type Numbers struct {
	A int `json:"a"`
	B int `json:"b"`
}

func main() {
	r := gin.Default()

	r.POST("/sum", func(c *gin.Context) {
		var n Numbers
		if err := c.ShouldBindJSON(&n); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid body"})
			return
		}
		if n.A < 0 || n.B < 0 {
			c.JSON(http.StatusBadRequest, gin.H{"error": "inputs must be non-negative"})
			return
		}
		c.JSON(http.StatusOK, gin.H{"result": n.A + n.B})
	})

	r.POST("/product", func(c *gin.Context) {
		var n Numbers
		if err := c.ShouldBindJSON(&n); err != nil {
			c.JSON(http.StatusBadRequest, gin.H{"error": "invalid body"})
			return
		}
		if n.A < 0 || n.B < 0 {
			c.JSON(http.StatusBadRequest, gin.H{"error": "inputs must be non-negative"})
			return
		}
		c.JSON(http.StatusOK, gin.H{"result": n.A * n.B})
	})

	r.Run(":8034")
}

